from flask import Blueprint, jsonify, request

quotes_bp = Blueprint("quotes", __name__)


@quotes_bp.post("/quote")
def quote():
    data = request.get_json(silent=True) or {}
    unit_price = data["unitPrice"]
    quantity = data["quantity"]
    subtotal = unit_price * quantity
    if quantity >= 100:
        discount = 0.20
    elif quantity >= 10:
        discount = 0.10
    else:
        discount = 0.0
    total = round(subtotal * (1 - discount), 2)
    return jsonify({"subtotal": round(subtotal, 2), "discount": discount, "total": total})


@quotes_bp.post("/quote/bulk")
def quote_bulk():
    out = []
    for item in request.get_json(silent=True) or []:
        subtotal = item["unitPrice"] * item["quantity"]
        if item["quantity"] >= 100:
            discount = 0.20
        elif item["quantity"] >= 10:
            discount = 0.10
        else:
            discount = 0.0
        total = round(subtotal * (1 - discount), 2)
        out.append({"subtotal": round(subtotal, 2), "discount": discount, "total": total})
    return jsonify(out)

