    for i in request.get_json(silent=True) or []:
        subtotal = i["unitPrice"] * i["quantity"]
        discount = 0.20 if i["quantity"] >= 50 else 0.0
        out.append({"subtotal": round(subtotal, 2), "discount": discount,
